// Applies db/migrations/*.sql in filename order and records each in schema_migrations (SPEC §5.3).
//
//   node scripts/migrate.mjs          → DATABASE_URL
//   node scripts/migrate.mjs --test   → DATABASE_URL_TEST (a Tiger fork; never production)
//
// Reads .env.local when present, without overriding variables already set (e.g. by Docker).
// A file whose first line is `-- migrate:no-transaction` runs statement by statement outside a
// transaction (needed for TimescaleDB continuous aggregates); every other file runs in one transaction.
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import postgres from 'postgres';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const migrationsDir = join(root, 'db', 'migrations');
const useTest = process.argv.includes('--test');
const varName = useTest ? 'DATABASE_URL_TEST' : 'DATABASE_URL';

const envFile = join(root, '.env.local');
if (existsSync(envFile)) {
  for (const [k, v] of Object.entries(parseEnv(readFileSync(envFile, 'utf8')))) {
    if (process.env[k] === undefined) process.env[k] = v;
  }
}

const url = process.env[varName];
if (!url) {
  console.error(`migrate: ${varName} is not set`);
  process.exit(1);
}

const NO_TX = '-- migrate:no-transaction';
const LOCK_KEY = 727_270_001; // arbitrary constant: one migrator at a time

const sql = postgres(url, { ssl: 'require', max: 1, onnotice: () => {} });

try {
  const conn = await sql.reserve();
  try {
    await conn`SELECT pg_advisory_lock(${LOCK_KEY})`;
    await conn`CREATE TABLE IF NOT EXISTS schema_migrations (
      version    text PRIMARY KEY,
      applied_at timestamptz NOT NULL DEFAULT now()
    )`;
    const applied = new Set((await conn`SELECT version FROM schema_migrations`).map((r) => r.version));

    const files = readdirSync(migrationsDir).filter((f) => f.endsWith('.sql')).sort();
    let ran = 0;
    for (const file of files) {
      const version = file.replace(/\.sql$/, '');
      if (applied.has(version)) continue;
      const text = readFileSync(join(migrationsDir, file), 'utf8');
      process.stdout.write(`migrate: applying ${file} ... `);

      if (text.startsWith(NO_TX)) {
        const statements = splitStatements(text);
        for (const [i, stmt] of statements.entries()) {
          try {
            await conn.unsafe(stmt);
          } catch (err) {
            console.error(`\nmigrate: ${file} failed at statement ${i + 1}/${statements.length}:\n${stmt}\n`);
            console.error('migrate: this file is not transactional; earlier statements were kept. Fix and drop them, or finish by hand.');
            throw err;
          }
        }
        await conn`INSERT INTO schema_migrations (version) VALUES (${version})`;
      } else {
        await conn.unsafe('BEGIN');
        try {
          await conn.unsafe(text);
          await conn`INSERT INTO schema_migrations (version) VALUES (${version})`;
          await conn.unsafe('COMMIT');
        } catch (err) {
          await conn.unsafe('ROLLBACK');
          throw err;
        }
      }
      console.log('done');
      ran++;
    }
    console.log(ran ? `migrate: applied ${ran} migration(s) to ${varName}` : `migrate: ${varName} is up to date`);
    await conn`SELECT pg_advisory_unlock(${LOCK_KEY})`;
  } finally {
    conn.release();
  }
} catch (err) {
  console.error(`migrate: ${err.message}`);
  process.exitCode = 1;
} finally {
  await sql.end({ timeout: 5 });
}

/** Splits a migration into statements. Our migrations contain no strings or dollar-quotes with ';' or '--'. */
function splitStatements(text) {
  return text
    .replace(/--[^\n]*/g, '')
    .split(';')
    .map((s) => s.trim())
    .filter(Boolean);
}

/** Minimal KEY=VALUE parser for .env.local (supports quotes and # comments). */
function parseEnv(src) {
  const out = {};
  for (const line of src.split(/\r?\n/)) {
    const m = line.match(/^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)\s*$/);
    if (!m) continue;
    let v = m[2];
    if (/^(['"]).*\1$/.test(v)) v = v.slice(1, -1);
    else v = v.replace(/\s+#.*$/, '');
    out[m[1]] = v;
  }
  return out;
}

