import "server-only";
import { z } from "zod";

// SPEC §8. Server-only variables, validated once at server start (src/instrumentation.ts) and
// lazily on first use. Never parsed at import time: `next build` runs without secrets.
// Error messages name missing variables but never print values.

/** Treat `KEY=` (empty) as unset, which is how docker env files usually leave optional vars. */
const opt = <T extends z.ZodType>(schema: T) =>
  z.preprocess((v) => (typeof v === "string" && v.trim() === "" ? undefined : v), schema);

const required = opt(z.string().min(1, "is required"));

const schema = z
  .object({
    NODE_ENV: opt(z.enum(["development", "production", "test"]).default("development")),

    AUTH0_DOMAIN: required,
    AUTH0_CLIENT_ID: required,
    AUTH0_CLIENT_SECRET: required,
    AUTH0_SECRET: opt(z.string().min(32, "must be at least 32 characters (openssl rand -hex 32)")),
    APP_BASE_URL: opt(z.url().optional()),

    DATABASE_URL: opt(z.string().regex(/^postgres(ql)?:\/\//, "must be a postgres:// connection string")),
    DB_POOL_MAX: opt(z.coerce.number().int().min(1).max(50).default(5)),
    DATABASE_URL_TEST: opt(z.string().regex(/^postgres(ql)?:\/\//).optional()),

    GEMINI_API_KEY: required,
    GEMINI_MODEL: opt(z.string().default("gemini-3.8-flash")),
    GEMINI_SEARCH_MODEL: opt(z.string().default("gemini-3.8-flash")),

    DATAANDAPIS_KEY: required,
    OFF_BASE_URL: opt(z.url().default("https://world.openfoodfacts.org")),
    OFF_USER_AGENT: required,
    RECIPE_FETCH_USER_AGENT: required,

    ELEVENLABS_API_KEY: opt(z.string().optional()),
    ELEVENLABS_VOICE_ID: opt(z.string().default("JBFqnCBsd6RMkjVDRZzb")),
    ELEVENLABS_MODEL_ID: opt(z.string().default("eleven_flash_v2_5")),

    DEFAULT_TZ: opt(z.string().default("America/Vancouver")),
  })
  .superRefine((e, ctx) => {
    if (e.NODE_ENV === "production" && !e.APP_BASE_URL) {
      ctx.addIssue({ code: "custom", path: ["APP_BASE_URL"], message: "is required in production" });
    }
    if (!isValidTimeZone(e.DEFAULT_TZ)) {
      ctx.addIssue({ code: "custom", path: ["DEFAULT_TZ"], message: "must be an IANA time zone" });
    }
  });

export type Env = z.infer<typeof schema>;

let cached: Env | null = null;

/** Parses `source` (default `process.env`). Throws one error listing every bad variable by name. */
export function parseEnv(source: Record<string, string | undefined> = process.env): Env {
  const r = schema.safeParse(source);
  if (!r.success) {
    const lines = r.error.issues.map((i) => `  - ${i.path.join(".")} ${i.message}`);
    throw new Error(`Invalid server environment (see .env.example):\n${lines.join("\n")}`);
  }
  return r.data;
}

/** Validated server env, parsed on first call and memoized. */
export function env(): Env {
  return (cached ??= parseEnv());
}

export function isValidTimeZone(tz: string): boolean {
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: tz });
    return true;
  } catch {
    return false;
  }
}

