import "server-only";
import postgres, { type Sql } from "postgres";
import { env } from "./env";

// One small postgres.js pool per Node process (SPEC §3.1: Tiger free services have no pooler).
// Created on first use, not at import, so `next build` never needs DATABASE_URL.
//
// Type parsing (shared by every workstream):
//   numeric (1700), int8 (20) → JS number   (contracts use `number`; our values fit in 2^53)
//   date (1082)               → 'YYYY-MM-DD' string, never a Date (a Date would shift by the TZ)
//   timestamptz               → Date (postgres.js default); call .toISOString() for contracts
// Write dates to `date` columns as 'YYYY-MM-DD' strings.

const keepText = (x: string) => x;

function createPool(): Sql {
  const e = env();
  return postgres(e.DATABASE_URL, {
    max: e.DB_POOL_MAX,
    ssl: "require",
    onnotice: () => {},
    types: {
      numeric: { to: 1700, from: [1700], serialize: (x: number) => String(x), parse: (x: string) => Number(x) },
      int8: { to: 20, from: [20], serialize: (x: number) => String(x), parse: (x: string) => Number(x) },
      date: { to: 1082, from: [1082], serialize: keepText, parse: keepText },
    },
  });
}

// Survive Next dev hot reloads without leaking pools.
const g = globalThis as typeof globalThis & { __miseSql?: Sql };

export function getSql(): Sql {
  return (g.__miseSql ??= createPool());
}

/**
 * The shared pool, usable exactly like a postgres.js `sql` instance:
 *   const rows = await sql`SELECT … WHERE user_id = ${user.id}`;
 *   await sql.begin(async (tx) => { … });
 */
export const sql: Sql = new Proxy((() => {}) as unknown as Sql, {
  apply: (_t, _this, args) => (getSql() as unknown as (...a: unknown[]) => unknown)(...args),
  get: (_t, prop) => {
    const target = getSql() as unknown as Record<PropertyKey, unknown>;
    const v = target[prop];
    return typeof v === "function" ? (v as (...a: unknown[]) => unknown).bind(target) : v;
  },
});

