import { Auth0Client } from "@auth0/nextjs-auth0/server";

// SPEC F1. Reads AUTH0_DOMAIN, AUTH0_CLIENT_ID, AUTH0_CLIENT_SECRET, AUTH0_SECRET and APP_BASE_URL
// from the environment (validated by src/lib/env.ts at server start). The constructor does not
// need them, so importing this during `next build` is safe.
// No `server-only` import here: src/proxy.ts imports this module.
export const auth0 = new Auth0Client({
  signInReturnToPath: "/today",
});

import { NextResponse, type NextRequest } from "next/server";
import type { ApiError } from "@/contracts";
import { auth0 } from "@/lib/auth0";

// SPEC F1 / §13. auth0.middleware() mounts /auth/* and rolls the session cookie on every request.
// After that, this gate enforces sign-in:
//   - /api/*  without a session → 401 ApiError JSON (F1 AC1)
//   - pages   without a session → redirect to /auth/login?returnTo=<path>
// Route handlers still call requireUser() themselves (defense in depth, and to get the user id).

const PUBLIC_PATHS = new Set(["/", "/api/health"]);

export async function proxy(request: NextRequest) {
  const authResponse = await auth0.middleware(request);
  const { pathname, search } = request.nextUrl;

  if (pathname === "/auth" || pathname.startsWith("/auth/")) return authResponse;
  if (PUBLIC_PATHS.has(pathname)) return authResponse;
  // Static files from public/ (WASM, models, images). Pages and API routes never have an extension.
  if (/\/[^/]+\.[a-z0-9]+$/i.test(pathname)) return authResponse;

  const session = await auth0.getSession(request);
  if (session) return authResponse;

  if (pathname === "/api" || pathname.startsWith("/api/")) {
    const body: ApiError = { error: { code: "UNAUTHORIZED", message: "Sign in required" } };
    return NextResponse.json(body, { status: 401 });
  }

  const login = new URL("/auth/login", request.url);
  login.searchParams.set("returnTo", pathname + search);
  return NextResponse.redirect(login);
}

export const config = {
  matcher: ["/((?!_next/static|_next/image|favicon.ico|sitemap.xml|robots.txt).*)"],
};

import "server-only";
import { redirect } from "next/navigation";
import { cache } from "react";
import type { Allergen, DietFlag, UUID } from "@/contracts";
import { auth0 } from "./auth0";
import { sql } from "./db";
import { env } from "./env";

export interface CurrentUser {
  id: UUID;
  sub: string;
  email: string | null;
  tz: string;
  diets: DietFlag[];
  allergens: Allergen[];
  onboarded: boolean;
}

/**
 * SPEC F1. Call first in every route handler, Server Action and protected page:
 *   const user = await requireUser();
 * Upserts the `users` row keyed by Auth0 `sub` (never merged by email) and returns it.
 * Without a session it redirects to /auth/login. src/proxy.ts normally answers first
 * (401 JSON for /api/*), so this only fires if a route is ever left out of the proxy.
 * Memoized per request, so a layout and its page share one DB round trip.
 */
export const requireUser = cache(async (): Promise<CurrentUser> => {
  const session = await auth0.getSession();
  if (!session) redirect("/auth/login");

  const u = session.user;
  const [row] = await sql<
    { id: string; auth0_sub: string; email: string | null; tz: string; diets: string[]; allergens: string[]; onboarded_at: Date | null }[]
  >`
    INSERT INTO users (auth0_sub, email, display_name, avatar_url, tz)
    VALUES (${u.sub}, ${u.email ?? null}, ${u.name ?? null}, ${u.picture ?? null}, ${env().DEFAULT_TZ})
    ON CONFLICT (auth0_sub) DO UPDATE SET
      last_seen_at = now(),
      email        = COALESCE(EXCLUDED.email, users.email),
      display_name = COALESCE(users.display_name, EXCLUDED.display_name),
      avatar_url   = COALESCE(EXCLUDED.avatar_url, users.avatar_url)
    RETURNING id, auth0_sub, email, tz, diets, allergens, onboarded_at
  `;

  return {
    id: row.id,
    sub: row.auth0_sub,
    email: row.email,
    tz: row.tz,
    diets: row.diets as DietFlag[],
    allergens: row.allergens as Allergen[],
    onboarded: row.onboarded_at !== null,
  };
});

// Runs once when the Next.js server starts (not during `next build`).
// SPEC §8: validate the server environment at boot and fail fast with the names of bad variables.
export async function register() {
  if (process.env.NEXT_RUNTIME === "nodejs") {
    const { env } = await import("./lib/env");
    env();
  }
}

