import type { DisplayUnit, UnitDim } from "@/contracts";

// SPEC §5.4. Base units: g (mass), ml (volume), count. Pure; safe on client and server.
// Cross-dimension conversion only through an explicit bridge. Never guess.

const FACTORS: Record<DisplayUnit, { dim: UnitDim; factor: number }> = {
  g: { dim: "mass", factor: 1 },
  kg: { dim: "mass", factor: 1000 },
  oz: { dim: "mass", factor: 28.3495 },
  lb: { dim: "mass", factor: 453.592 },
  ml: { dim: "volume", factor: 1 },
  l: { dim: "volume", factor: 1000 },
  tsp: { dim: "volume", factor: 4.92892 },
  tbsp: { dim: "volume", factor: 14.7868 },
  cup: { dim: "volume", factor: 236.588 },
  fl_oz: { dim: "volume", factor: 29.5735 },
  pcs: { dim: "count", factor: 1 },
};

export const DISPLAY_UNITS = Object.keys(FACTORS) as DisplayUnit[];
export const BASE_UNIT: Record<UnitDim, DisplayUnit> = { mass: "g", volume: "ml", count: "pcs" };

export function unitDim(unit: DisplayUnit): UnitDim {
  return FACTORS[unit].dim;
}

export function unitsForDim(dim: UnitDim): DisplayUnit[] {
  return DISPLAY_UNITS.filter((u) => FACTORS[u].dim === dim);
}

export function toBase(qty: number, unit: DisplayUnit): { dim: UnitDim; qtyBase: number } | null {
  const f = FACTORS[unit];
  if (!f || !Number.isFinite(qty)) return null;
  return { dim: f.dim, qtyBase: qty * f.factor };
}

/** Base quantity → `unit`. Null when `unit` is not in `dim` (use convertBetween first). */
export function fromBase(qtyBase: number, dim: UnitDim, unit: DisplayUnit): number | null {
  const f = FACTORS[unit];
  if (!f || f.dim !== dim || !Number.isFinite(qtyBase)) return null;
  return qtyBase / f.factor;
}

/**
 * Converts a base quantity between dimensions. count↔mass uses gramsPerUnit, volume↔mass uses
 * densityGPerMl, count↔volume needs both. Missing or non-positive bridge → null.
 */
export function convertBetween(
  qtyBase: number,
  from: UnitDim,
  to: UnitDim,
  bridge: { gramsPerUnit?: number | null; densityGPerMl?: number | null },
): number | null {
  if (!Number.isFinite(qtyBase)) return null;
  if (from === to) return qtyBase;
  const grams = toGrams(qtyBase, from, bridge);
  return grams === null ? null : fromGrams(grams, to, bridge);
}

function positive(x: number | null | undefined): number | null {
  return typeof x === "number" && Number.isFinite(x) && x > 0 ? x : null;
}

function toGrams(q: number, dim: UnitDim, b: { gramsPerUnit?: number | null; densityGPerMl?: number | null }) {
  if (dim === "mass") return q;
  const k = dim === "count" ? positive(b.gramsPerUnit) : positive(b.densityGPerMl);
  return k === null ? null : q * k;
}

function fromGrams(g: number, dim: UnitDim, b: { gramsPerUnit?: number | null; densityGPerMl?: number | null }) {
  if (dim === "mass") return g;
  const k = dim === "count" ? positive(b.gramsPerUnit) : positive(b.densityGPerMl);
  return k === null ? null : g / k;
}

// Case-sensitive cookbook shorthands checked before lowercasing: T = tablespoon, t = teaspoon.
const CASE_SENSITIVE: Record<string, DisplayUnit> = { T: "tbsp", Tb: "tbsp", Tbs: "tbsp", t: "tsp" };

const ALIASES: Record<string, DisplayUnit> = {};
function alias(unit: DisplayUnit, ...names: string[]) {
  for (const n of [unit, ...names]) ALIASES[n] = unit;
}
alias("g", "gram", "grams", "gramme", "grammes", "gr", "grm", "gm", "gms");
alias("kg", "kgs", "kilogram", "kilograms", "kilogramme", "kilogrammes", "kilo", "kilos");
alias("oz", "ozs", "ounce", "ounces");
alias("lb", "lbs", "pound", "pounds");
alias("ml", "mls", "millilitre", "millilitres", "milliliter", "milliliters", "cc");
alias("l", "ltr", "ltrs", "litre", "litres", "liter", "liters");
alias("tsp", "tsps", "teaspoon", "teaspoons", "tsp.");
alias("tbsp", "tbsps", "tbs", "tbl", "tbls", "tablespoon", "tablespoons");
alias("cup", "cups", "c");
alias("fl_oz", "fl oz", "floz", "fl ozs", "fluid ounce", "fluid ounces", "fl ounce", "fl ounces");
alias("pcs", "pc", "piece", "pieces", "each", "ea", "clove", "cloves", "egg", "eggs", "unit", "units", "count", "ct", "whole");

/** 'Tbsp' | 'tablespoons' → 'tbsp'. Null for anything unknown (including 'pinch', 'to taste'). */
export function parseUnit(raw: string): DisplayUnit | null {
  const trimmed = raw.trim().replace(/\.+$/, "");
  if (trimmed in CASE_SENSITIVE) return CASE_SENSITIVE[trimmed];
  const key = trimmed.toLowerCase().replace(/\./g, "").replace(/[\s_-]+/g, " ");
  return ALIASES[key] ?? null;
}

const LABEL: Record<DisplayUnit, string> = {
  g: "g", kg: "kg", oz: "oz", lb: "lb", ml: "ml", l: "L", tsp: "tsp", tbsp: "tbsp", cup: "cup", fl_oz: "fl oz", pcs: "pcs",
};

/** Rounds for display: ≥100 → integer, ≥10 → 1 decimal, else 2 decimals; trailing zeros dropped. */
export function roundForDisplay(x: number): number {
  const a = Math.abs(x);
  const digits = a >= 100 ? 0 : a >= 10 ? 1 : 2;
  const p = 10 ** digits;
  const r = Math.round(x * p) / p;
  return Object.is(r, -0) ? 0 : r;
}

/**
 * '1.5 kg', '350 g', '3 pcs'. Uses `preferred` when it belongs to `dim`; otherwise g/kg and
 * ml/L switch at 1000. Never shows a unit from another dimension.
 */
export function formatQty(qtyBase: number, dim: UnitDim, preferred?: DisplayUnit): string {
  let unit: DisplayUnit;
  if (preferred && FACTORS[preferred]?.dim === dim) unit = preferred;
  else if (dim === "mass") unit = Math.abs(qtyBase) >= 1000 ? "kg" : "g";
  else if (dim === "volume") unit = Math.abs(qtyBase) >= 1000 ? "l" : "ml";
  else unit = "pcs";

  const value = roundForDisplay(qtyBase / FACTORS[unit].factor);
  let label = LABEL[unit];
  if (unit === "pcs" && value === 1) label = "pc";
  if (unit === "cup" && value !== 1) label = "cups";
  return `${value} ${label}`;
}

// SPEC F2 / §1.4. Barcode → canonical GTIN. Pure; used by the client scanner and the server.
//
// Rules (team decisions, see docs/johnny-verify.md):
//   - Spaces, hyphens and dots are separators and are removed. Any other non-digit → non_numeric.
//   - UPC-A (12) is left-padded to GTIN-13.
//   - EAN-8 keeps its 8 digits for provider calls (`lookupCode`) and is padded to 13 for `gtin`.
//   - UPC-E (8, number system 0/1) expands to UPC-A, then GTIN-13. A code the scanner reports as
//     upc_e is always expanded; a typed/unknown 8-digit code is EAN-8 if its check digit passes,
//     else UPC-E if that check passes.
//   - GTIN-14 with indicator 0 is the same item as its GTIN-13 and drops the leading 0.

export type BarcodeFormat = "ean_13" | "ean_8" | "upc_a" | "upc_e" | "unknown";
export type GtinInvalidReason = "length" | "check_digit" | "non_numeric";
export type GtinKind = "ean13" | "upca" | "ean8" | "upce" | "gtin14";

export type GtinResult =
  | {
      ok: true;
      /** Canonical 13/14-digit key: products.gtin, pantry_items.gtin, cache key. */
      gtin: string;
      /** Digits to send to barcode providers (the EAN-8 itself for EAN-8, else `gtin`). */
      lookupCode: string;
      kind: GtinKind;
    }
  | { ok: false; reason: GtinInvalidReason };

/** GS1 mod-10 check digit for `body` (all digits except the check digit). */
export function gs1CheckDigit(body: string): number {
  let sum = 0;
  for (let i = 0; i < body.length; i++) {
    const digit = body.charCodeAt(body.length - 1 - i) - 48;
    sum += digit * (i % 2 === 0 ? 3 : 1);
  }
  return (10 - (sum % 10)) % 10;
}

/** True when the last digit of an all-digit `code` is its GS1 check digit. */
export function hasValidCheckDigit(code: string): boolean {
  if (!/^\d{2,}$/.test(code)) return false;
  return gs1CheckDigit(code.slice(0, -1)) === code.charCodeAt(code.length - 1) - 48;
}

/** Expands an 8-digit UPC-E (number system 0 or 1) to 12-digit UPC-A, or null if it can't be one. */
export function expandUpcE(code8: string): string | null {
  if (!/^[01]\d{7}$/.test(code8)) return null;
  const n = code8[0];
  const [d1, d2, d3, d4, d5, d6] = code8.slice(1, 7);
  const check = code8[7];
  let body: string;
  switch (d6) {
    case "0":
    case "1":
    case "2":
      body = `${n}${d1}${d2}${d6}0000${d3}${d4}${d5}`;
      break;
    case "3":
      body = `${n}${d1}${d2}${d3}00000${d4}${d5}`;
      break;
    case "4":
      body = `${n}${d1}${d2}${d3}${d4}00000${d5}`;
      break;
    default:
      body = `${n}${d1}${d2}${d3}${d4}${d5}0000${d6}`;
  }
  return body + check;
}

export function normalizeBarcode(raw: string, format: BarcodeFormat = "unknown"): GtinResult {
  const code = raw.replace(/[\s.-]+/g, "");
  if (code === "") return { ok: false, reason: "length" };
  if (/\D/.test(code)) return { ok: false, reason: "non_numeric" };

  switch (code.length) {
    case 8:
      return normalize8(code, format);
    case 12:
      return hasValidCheckDigit(code)
        ? { ok: true, gtin: `0${code}`, lookupCode: `0${code}`, kind: "upca" }
        : { ok: false, reason: "check_digit" };
    case 13:
      return hasValidCheckDigit(code)
        ? { ok: true, gtin: code, lookupCode: code, kind: "ean13" }
        : { ok: false, reason: "check_digit" };
    case 14: {
      if (!hasValidCheckDigit(code)) return { ok: false, reason: "check_digit" };
      // Indicator 0: identical item to the GTIN-13 (same check digit, weights align from the right).
      const gtin = code.startsWith("0") ? code.slice(1) : code;
      return { ok: true, gtin, lookupCode: gtin, kind: "gtin14" };
    }
    default:
      return { ok: false, reason: "length" };
  }
}

function normalize8(code: string, format: BarcodeFormat): GtinResult {
  const asEan8 = (): GtinResult => ({ ok: true, gtin: code.padStart(13, "0"), lookupCode: code, kind: "ean8" });
  const asUpcE = (): GtinResult | null => {
    const upca = expandUpcE(code);
    if (!upca || !hasValidCheckDigit(upca)) return null;
    return { ok: true, gtin: `0${upca}`, lookupCode: `0${upca}`, kind: "upce" };
  };

  if (format === "upc_e") return asUpcE() ?? { ok: false, reason: "check_digit" };
  if (hasValidCheckDigit(code)) return asEan8();
  if (format === "ean_8") return { ok: false, reason: "check_digit" };
  return asUpcE() ?? { ok: false, reason: "check_digit" };
}

import { describe, expect, it } from "vitest";
import type { DisplayUnit, UnitDim } from "@/contracts";
import { convertBetween, formatQty, fromBase, isDisplayUnit, parseUnit, roundForDisplay, toBase, unitsForDim } from "./units";

describe("toBase: every factor from SPEC §5.4", () => {
  const cases: Array<[DisplayUnit, UnitDim, number]> = [
    ["g", "mass", 1],
    ["kg", "mass", 1000],
    ["oz", "mass", 28.3495],
    ["lb", "mass", 453.592],
    ["ml", "volume", 1],
    ["l", "volume", 1000],
    ["tsp", "volume", 4.92892],
    ["tbsp", "volume", 14.7868],
    ["cup", "volume", 236.588],
    ["fl_oz", "volume", 29.5735],
    ["pcs", "count", 1],
  ];
  it.each(cases)("1 %s = %s base × %d", (unit, dim, factor) => {
    expect(toBase(1, unit)).toEqual({ dim, qtyBase: factor });
  });

  it("cup → ml", () => {
    expect(toBase(2, "cup")!.qtyBase).toBeCloseTo(473.176, 6);
    expect(fromBase(473.176, "volume", "cup")).toBeCloseTo(2, 9);
  });

  it("kg ↔ g", () => {
    expect(toBase(1.5, "kg")).toEqual({ dim: "mass", qtyBase: 1500 });
    expect(fromBase(1500, "mass", "kg")).toBe(1.5);
    expect(fromBase(250, "mass", "g")).toBe(250);
  });

  it("rejects non-finite quantities and unknown units", () => {
    expect(toBase(Number.NaN, "g")).toBeNull();
    expect(toBase(Infinity, "g")).toBeNull();
    expect(toBase(1, "constructor" as DisplayUnit)).toBeNull();
  });
});

describe("fromBase", () => {
  it("returns null when the unit is in another dimension", () => {
    expect(fromBase(100, "mass", "ml")).toBeNull();
    expect(fromBase(3, "count", "g")).toBeNull();
  });
});

describe("convertBetween", () => {
  it("same dimension is identity, no bridge needed", () => {
    expect(convertBetween(250, "mass", "mass", {})).toBe(250);
  });
  it("count ↔ mass via gramsPerUnit", () => {
    expect(convertBetween(3, "count", "mass", { gramsPerUnit: 50 })).toBe(150);
    expect(convertBetween(150, "mass", "count", { gramsPerUnit: 50 })).toBe(3);
  });
  it("volume ↔ mass via density", () => {
    expect(convertBetween(100, "volume", "mass", { densityGPerMl: 1.03 })).toBeCloseTo(103, 9);
    expect(convertBetween(103, "mass", "volume", { densityGPerMl: 1.03 })).toBeCloseTo(100, 9);
  });
  it("count ↔ volume needs both bridges", () => {
    expect(convertBetween(2, "count", "volume", { gramsPerUnit: 50, densityGPerMl: 1 })).toBe(100);
    expect(convertBetween(2, "count", "volume", { gramsPerUnit: 50 })).toBeNull();
  });
  it("no bridge → null, never a guess", () => {
    expect(convertBetween(1, "volume", "mass", {})).toBeNull();
    expect(convertBetween(1, "count", "mass", { gramsPerUnit: null })).toBeNull();
    expect(convertBetween(1, "mass", "volume", { densityGPerMl: null })).toBeNull();
  });
  it("zero or negative bridges are treated as missing", () => {
    expect(convertBetween(1, "count", "mass", { gramsPerUnit: 0 })).toBeNull();
    expect(convertBetween(1, "volume", "mass", { densityGPerMl: -1 })).toBeNull();
  });
});

describe("parseUnit aliases", () => {
  const cases: Array<[string, DisplayUnit]> = [
    ["g", "g"], ["grams", "g"], ["Gram", "g"], ["gr", "g"],
    ["kg", "kg"], ["Kilograms", "kg"], ["kilo", "kg"],
    ["oz", "oz"], ["ounces", "oz"],
    ["lb", "lb"], ["lbs", "lb"], ["Pounds", "lb"],
    ["ml", "ml"], ["mL", "ml"], ["millilitres", "ml"], ["milliliters", "ml"],
    ["l", "l"], ["L", "l"], ["litre", "l"], ["liters", "l"],
    ["tsp", "tsp"], ["teaspoons", "tsp"], ["tsp.", "tsp"], ["t", "tsp"],
    ["tbsp", "tbsp"], ["Tbsp", "tbsp"], ["TBSP", "tbsp"], ["tablespoons", "tbsp"], ["tbs", "tbsp"], ["T", "tbsp"],
    ["cup", "cup"], ["Cups", "cup"], ["c", "cup"],
    ["fl oz", "fl_oz"], ["fl. oz.", "fl_oz"], ["fluid ounces", "fl_oz"], ["fl_oz", "fl_oz"],
    ["pcs", "pcs"], ["piece", "pcs"], ["each", "pcs"], ["clove", "pcs"], ["cloves", "pcs"], ["egg", "pcs"], ["eggs", "pcs"],
    ["  grams  ", "g"],
  ];
  it.each(cases)("%j → %s", (raw, unit) => {
    expect(parseUnit(raw)).toBe(unit);
  });
  it.each(["pinch", "to taste", "dash", "handful", "", "constructor", "toString", "__proto__"])("%j → null", (raw) => {
    expect(parseUnit(raw)).toBeNull();
  });
});

describe("formatQty", () => {
  it("auto-picks g/kg and ml/L", () => {
    expect(formatQty(350, "mass")).toBe("350 g");
    expect(formatQty(1500, "mass")).toBe("1.5 kg");
    expect(formatQty(750, "volume")).toBe("750 ml");
    expect(formatQty(1890, "volume")).toBe("1.89 L");
  });
  it("counts", () => {
    expect(formatQty(3, "count")).toBe("3 pcs");
    expect(formatQty(1, "count")).toBe("1 pc");
  });
  it("honours a preferred unit in the same dimension", () => {
    expect(formatQty(453.592, "mass", "lb")).toBe("1 lb");
    expect(formatQty(473.176, "volume", "cup")).toBe("2 cups");
    expect(formatQty(236.588, "volume", "cup")).toBe("1 cup");
    expect(formatQty(500, "mass", "kg")).toBe("0.5 kg");
  });
  it("ignores a preferred unit from another dimension", () => {
    expect(formatQty(350, "mass", "ml")).toBe("350 g");
  });
  it("never shows raw float noise", () => {
    expect(formatQty(0.1 + 0.2, "mass")).toBe("0.3 g");
    expect(formatQty(12.345, "mass")).toBe("12.3 g");
    expect(formatQty(0, "mass")).toBe("0 g");
  });
});

describe("helpers", () => {
  it("roundForDisplay", () => {
    expect(roundForDisplay(123.6)).toBe(124);
    expect(roundForDisplay(-0.001)).toBe(0);
  });
  it("isDisplayUnit / unitsForDim", () => {
    expect(isDisplayUnit("tbsp")).toBe(true);
    expect(isDisplayUnit("constructor")).toBe(false);
    expect(unitsForDim("count")).toEqual(["pcs"]);
    expect(unitsForDim("mass")).toEqual(["g", "kg", "oz", "lb"]);
  });
});

import { describe, expect, it } from "vitest";
import { expandUpcE, gs1CheckDigit, hasValidCheckDigit, normalizeBarcode } from "./gtin";

describe("check digit", () => {
  it("computes GS1 mod-10", () => {
    expect(gs1CheckDigit("301762042200")).toBe(3); // Nutella 3017620422003
    expect(gs1CheckDigit("03600029145")).toBe(2); // UPC-A 036000291452
    expect(gs1CheckDigit("9638507")).toBe(4); // EAN-8 96385074
  });
  it("validates", () => {
    expect(hasValidCheckDigit("3017620422003")).toBe(true);
    expect(hasValidCheckDigit("3017620422004")).toBe(false);
    expect(hasValidCheckDigit("abc")).toBe(false);
  });
});

describe("normalizeBarcode", () => {
  it("valid EAN-13 stays as-is", () => {
    expect(normalizeBarcode("3017620422003")).toEqual({ ok: true, gtin: "3017620422003", lookupCode: "3017620422003", kind: "ean13" });
  });

  it("UPC-A is left-padded to GTIN-13 (F2 AC2)", () => {
    expect(normalizeBarcode("036000291452")).toEqual({ ok: true, gtin: "0036000291452", lookupCode: "0036000291452", kind: "upca" });
  });

  it("EAN-8 keeps 8 digits for lookup and pads the key to 13", () => {
    expect(normalizeBarcode("96385074")).toEqual({ ok: true, gtin: "0000096385074", lookupCode: "96385074", kind: "ean8" });
    expect(normalizeBarcode("96385074", "ean_8")).toMatchObject({ ok: true, kind: "ean8" });
  });

  it("bad check digit (F2 AC2)", () => {
    expect(normalizeBarcode("3017620422004")).toEqual({ ok: false, reason: "check_digit" });
    expect(normalizeBarcode("036000291453")).toEqual({ ok: false, reason: "check_digit" });
    expect(normalizeBarcode("96385075", "ean_8")).toEqual({ ok: false, reason: "check_digit" });
  });

  it("non-numeric: separators are removed, letters are rejected", () => {
    expect(normalizeBarcode(" 3017 6204-22003 ")).toMatchObject({ ok: true, gtin: "3017620422003" });
    expect(normalizeBarcode("3017.6204.22003")).toMatchObject({ ok: true, gtin: "3017620422003" });
    expect(normalizeBarcode("30176204x22003")).toEqual({ ok: false, reason: "non_numeric" });
    expect(normalizeBarcode("abc")).toEqual({ ok: false, reason: "non_numeric" });
  });

  it("wrong lengths", () => {
    for (const s of ["", "   ", "1234567", "123456789", "12345678901", "123456789012345"]) {
      expect(normalizeBarcode(s)).toEqual({ ok: false, reason: "length" });
    }
  });

  it("GTIN-14: indicator 0 collapses to GTIN-13, others stay 14", () => {
    expect(normalizeBarcode("03017620422003")).toEqual({ ok: true, gtin: "3017620422003", lookupCode: "3017620422003", kind: "gtin14" });
    const body = "1301762042200";
    const g14 = body + gs1CheckDigit(body);
    expect(normalizeBarcode(g14)).toEqual({ ok: true, gtin: g14, lookupCode: g14, kind: "gtin14" });
    expect(normalizeBarcode(body + ((gs1CheckDigit(body) + 1) % 10))).toEqual({ ok: false, reason: "check_digit" });
  });

  it("every canonical gtin matches the products.gtin CHECK (^[0-9]{13,14}$)", () => {
    for (const s of ["3017620422003", "036000291452", "96385074", "04252614", "03017620422003"]) {
      const r = normalizeBarcode(s);
      expect(r.ok && /^[0-9]{13,14}$/.test(r.gtin)).toBe(true);
    }
  });
});

describe("UPC-E", () => {
  it("expands per GS1 rules for each last-digit case", () => {
    expect(expandUpcE("04252614")).toBe("042100005264"); // d6 = 1
    expect(expandUpcE("01234505")).toBe("012000003455"); // d6 = 0 → 0 1 2 0 0000 3 4 5 + check 5
    expect(expandUpcE("01234531")).toBe("012300000451"); // d6 = 3
    expect(expandUpcE("01234541")).toBe("012340000051"); // d6 = 4
    expect(expandUpcE("01234567")).toBe("012345000067"); // d6 = 6
  });

  it("only number system 0 or 1", () => {
    expect(expandUpcE("24252614")).toBeNull();
    expect(expandUpcE("0425261")).toBeNull();
  });

  it("scanner-reported upc_e is expanded to GTIN-13", () => {
    expect(normalizeBarcode("04252614", "upc_e")).toEqual({ ok: true, gtin: "0042100005264", lookupCode: "0042100005264", kind: "upce" });
  });

  it("scanner-reported upc_e with a bad check digit is rejected", () => {
    expect(normalizeBarcode("04252615", "upc_e")).toEqual({ ok: false, reason: "check_digit" });
  });

  it("typed 8 digits: EAN-8 first, UPC-E when only that check passes", () => {
    // 04252614 fails the EAN-8 check but passes as UPC-E.
    expect(hasValidCheckDigit("04252614")).toBe(false);
    expect(normalizeBarcode("04252614")).toMatchObject({ ok: true, kind: "upce", gtin: "0042100005264" });
    // 96385074 is a valid EAN-8 (and starts with 9, so it can't be UPC-E anyway).
    expect(normalizeBarcode("96385074")).toMatchObject({ ok: true, kind: "ean8" });
  });
});

