import 'server-only';
import { normalizeIngredientName } from '@/server/recipes/parse';

// SPEC F5: pantry_items.normalized_name is computed server-side and must match the
// normalizedName that recipe matching computes for ingredient lines. So pantry names go
// through the SAME function as recipe ingredients (Hang's normalizeIngredientName, read-only),
// after stripping the two things only product names have:
//   - the product's brand (each comma-separated phrase of `brand`, as whole words)
//   - package-size text ("400 g", "2 x 500 ml", "12 ct", the EU estimated sign "e"/"℮")
// Team decision 2026-11-08: no marketing-adjective stripping.

const BOUNDARY_START = '(?<![\\p{L}\\p{N}])';
const BOUNDARY_END = '(?![\\p{L}\\p{N}])';
const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const SIZE_UNIT = '(?:kg|g|mg|ml|cl|dl|l|fl\\.?\\s*oz|oz|lbs?|ct|pcs|pc|pk|pack|count)';
const NUM = '\\d+(?:[.,]\\d+)?';
const PACKAGE_SIZE_RE = new RegExp(
  `${BOUNDARY_START}${NUM}\\s*(?:x\\s*${NUM}\\s*)?${SIZE_UNIT}\\.?(?:\\s*(?:e|℮)${BOUNDARY_END})?${BOUNDARY_END}`,
  'giu',
);

/** Removes brand phrases and package sizes from a product name. Never returns undefined; may return ''. */
export function stripBrandAndSize(name: string, brand?: string | null): string {
  let s = name.replace(/℮/g, ' ');
  for (const phrase of (brand ?? '').split(',').map((b) => b.trim()).filter(Boolean)) {
    s = s.replace(new RegExp(`${BOUNDARY_START}${escapeRe(phrase)}(?:'s)?${BOUNDARY_END}`, 'giu'), ' ');
  }
  s = s.replace(PACKAGE_SIZE_RE, ' ');
  return s.replace(/\s+/g, ' ').trim();
}

/**
 * normalized_name for a pantry item: brand and size stripped, then recipe normalization
 * (lowercase, descriptors like fresh/chopped removed, naive singular).
 * Falls back to normalizing the full name when stripping leaves nothing ("Nutella" by Nutella).
 */
export function normalizePantryName(name: string, brand?: string | null): string {
  const stripped = normalizeIngredientName(stripBrandAndSize(name, brand));
  if (stripped) return stripped;
  const full = normalizeIngredientName(name);
  return full || name.trim().toLowerCase();
}

// Calendar-date helpers in the user's time zone (SPEC F5 AC3, F15 local_date). Pure.

const ISO_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** Today's date ('YYYY-MM-DD') in IANA time zone `tz`. */
export function todayInTz(tz: string, now: Date = new Date()): string {
  // en-CA formats as YYYY-MM-DD.
  return new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
}

/** True for a real calendar date in 'YYYY-MM-DD' form (rejects 2026-02-30). */
export function isIsoDate(s: string): boolean {
  const m = ISO_DATE.exec(s);
  if (!m) return false;
  const d = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])));
  return d.getUTCFullYear() === Number(m[1]) && d.getUTCMonth() === Number(m[2]) - 1 && d.getUTCDate() === Number(m[3]);
}

/** Whole calendar days from `from` to `to` (both 'YYYY-MM-DD'). Negative when `to` is earlier. */
export function daysBetween(from: string, to: string): number {
  return Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86_400_000);
}

/** Days from today (in `tz`) until `isoDate`. 0 = today, negative = past date. */
export function daysUntil(isoDate: string, tz: string, now: Date = new Date()): number {
  return daysBetween(todayInTz(tz, now), isoDate);
}

/** 'YYYY-MM-DD' shifted by `days`. */
export function addDays(isoDate: string, days: number): string {
  const d = new Date(`${isoDate}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

import type { Allergen } from '@/contracts/domain';
import { ALLERGEN_KEYWORDS, checkDiet } from '@/server/diet/check';

// Pantry allergen tags (team decision 2026-11-08): the provider's or user's tags UNION whatever
// Hang's keyword map (server/diet/check.ts, read-only) finds in the item's name. Over-tagging only
// makes AI substitutions stricter, which is the safe direction.

export const ALL_ALLERGENS = Object.keys(ALLERGEN_KEYWORDS) as Allergen[];

export function isAllergen(x: unknown): x is Allergen {
  return typeof x === 'string' && Object.hasOwn(ALLERGEN_KEYWORDS, x);
}

/** Allergens whose keywords appear in any of `texts` (e.g. name and brand). */
export function detectAllergens(texts: Array<string | null | undefined>): Allergen[] {
  const lines = texts.filter((t): t is string => typeof t === 'string' && t.trim() !== '');
  if (lines.length === 0) return [];
  const found = new Set<Allergen>();
  for (const v of checkDiet(lines, { diets: [], allergens: ALL_ALLERGENS }).violations) {
    if (isAllergen(v.rule)) found.add(v.rule);
  }
  return ALL_ALLERGENS.filter((a) => found.has(a));
}

/** Union of given tags and name-detected tags, deduplicated, in enum order. */
export function pantryAllergenTags(given: readonly Allergen[] | null | undefined, name: string): Allergen[] {
  const set = new Set<Allergen>([...(given ?? []).filter(isAllergen), ...detectAllergens([name])]);
  return ALL_ALLERGENS.filter((a) => set.has(a));
}

import { describe, expect, it } from 'vitest';
import { normalizeIngredientName } from '@/server/recipes/parse';
import { detectAllergens, pantryAllergenTags } from './allergens';
import { addDays, daysBetween, daysUntil, isIsoDate, todayInTz } from './dates';
import { normalizePantryName, stripBrandAndSize } from './normalize';

describe('stripBrandAndSize', () => {
  it('removes each comma-separated brand phrase as whole words', () => {
    expect(stripBrandAndSize('Nutella Hazelnut Spread', 'Nutella, Ferrero')).toBe('Hazelnut Spread');
    expect(stripBrandAndSize('Kraft Smooth Peanut Butter', 'Kraft')).toBe('Smooth Peanut Butter');
    expect(stripBrandAndSize('Old El Paso Taco Shells', 'Old El Paso')).toBe('Taco Shells');
    expect(stripBrandAndSize("Kellogg's Corn Flakes", 'Kellogg')).toBe('Corn Flakes');
  });
  it('does not remove brand text inside other words', () => {
    expect(stripBrandAndSize('Krafty Cheese', 'Kraft')).toBe('Krafty Cheese');
  });
  it('removes package sizes and the EU estimated sign', () => {
    expect(stripBrandAndSize('Greek Yogurt 750 g', null)).toBe('Greek Yogurt');
    expect(stripBrandAndSize('Nutella 400 g e', 'Ferrero')).toBe('Nutella');
    expect(stripBrandAndSize('Milk 2 L', null)).toBe('Milk');
    expect(stripBrandAndSize('Sparkling Water 12 x 355 ml', null)).toBe('Sparkling Water');
    expect(stripBrandAndSize('Eggs 12 ct', null)).toBe('Eggs');
    expect(stripBrandAndSize('Olive oil 1.5L ℮', null)).toBe('Olive oil');
    expect(stripBrandAndSize('Butter 454g', null)).toBe('Butter');
  });
  it('keeps numbers that are not sizes', () => {
    expect(stripBrandAndSize('7 Grain Bread', null)).toBe('7 Grain Bread');
    expect(stripBrandAndSize('2% Milk', null)).toBe('2% Milk');
  });
});

describe('normalizePantryName', () => {
  it('matches recipe normalization once brand and size are gone', () => {
    expect(normalizePantryName('Kraft Smooth Peanut Butter', 'Kraft')).toBe(normalizeIngredientName('smooth peanut butter'));
    expect(normalizePantryName('Nutella Hazelnut Spread', 'Nutella, Ferrero')).toBe('hazelnut spread');
    expect(normalizePantryName('Fresh Baby Spinach 312 g', 'Compliments')).toBe(normalizeIngredientName('spinach'));
    expect(normalizePantryName('Large Eggs 12 ct', null)).toBe('egg');
    expect(normalizePantryName('Roma Tomatoes', null)).toBe('roma tomato');
  });
  it('falls back to the full name when stripping leaves nothing', () => {
    expect(normalizePantryName('Nutella', 'Nutella, Ferrero')).toBe('nutella');
    expect(normalizePantryName('400 g', null)).toBe(normalizeIngredientName('400 g') || '400 g');
  });
});

describe('dates', () => {
  it('todayInTz respects the time zone', () => {
    const now = new Date('2026-11-08T06:30:00Z'); // 23:30 the previous day in Vancouver (UTC-7)
    expect(todayInTz('America/Vancouver', now)).toBe('2026-11-07');
    expect(todayInTz('UTC', now)).toBe('2026-11-08');
  });
  it('daysUntil: today is 0, past dates are negative (F5 AC3)', () => {
    const now = new Date('2026-11-08T18:00:00Z');
    expect(daysUntil('2026-11-08', 'America/Vancouver', now)).toBe(0);
    expect(daysUntil('2026-11-10', 'America/Vancouver', now)).toBe(2);
    expect(daysUntil('2026-11-05', 'America/Vancouver', now)).toBe(-3);
  });
  it('daysBetween crosses month and year ends', () => {
    expect(daysBetween('2026-12-30', '2027-01-02')).toBe(3);
    expect(daysBetween('2028-02-28', '2028-03-01')).toBe(2);
  });
  it('isIsoDate rejects impossible dates', () => {
    expect(isIsoDate('2026-11-15')).toBe(true);
    expect(isIsoDate('2026-02-30')).toBe(false);
    expect(isIsoDate('2026-13-01')).toBe(false);
    expect(isIsoDate('26-11-15')).toBe(false);
  });
  it('addDays', () => {
    expect(addDays('2026-12-31', 1)).toBe('2027-01-01');
    expect(addDays('2026-11-08', -6)).toBe('2026-11-02');
  });
});

describe('allergens', () => {
  it('detects allergens in names', () => {
    expect(detectAllergens(['Almond Milk'])).toEqual(expect.arrayContaining(['tree_nut', 'milk']));
    expect(detectAllergens(['Smooth Peanut Butter'])).toEqual(expect.arrayContaining(['peanut', 'milk']));
    expect(detectAllergens(['Baby Spinach'])).toEqual([]);
    expect(detectAllergens([null, '', undefined])).toEqual([]);
  });
  it('unions given tags with detected ones, deduplicated in enum order', () => {
    expect(pantryAllergenTags(['soy', 'tree_nut'], 'Hazelnut spread')).toEqual(['tree_nut', 'soy']);
    expect(pantryAllergenTags(['fish'], 'Baby Spinach')).toEqual(['fish']);
    expect(pantryAllergenTags(null, 'Greek Yogurt')).toEqual(['milk']);
  });
  it('drops values that are not allergens', () => {
    expect(pantryAllergenTags(['celery' as never, 'egg'], 'Bread')).toEqual(['egg', 'wheat_gluten']);
  });
});

