import { requireUser } from '@/lib/current-user';
import { handleRouteError, jsonError, jsonErrorFromZod, jsonOk } from '@/lib/http';
import { deleteUserData, getProfile, updateProfile } from '@/server/pantry/profile';
import { updateMeSchema } from '@/server/pantry/validation';

export const runtime = 'nodejs';

// SPEC F1 + §7. GET/PATCH → UserProfile. DELETE → { ok: true } (Settings "Delete my data").

export async function GET() {
  try {
    const user = await requireUser();
    return jsonOk(await getProfile(user.id));
  } catch (err) {
    return handleRouteError(err);
  }
}

export async function PATCH(req: Request) {
  try {
    const user = await requireUser();
    const body = await req.json().catch(() => undefined);
    if (body === undefined) return jsonError('BAD_REQUEST', 'Body must be JSON');
    const parsed = updateMeSchema.safeParse(body);
    if (!parsed.success) return jsonErrorFromZod(parsed.error);
    return jsonOk(await updateProfile(user.id, parsed.data));
  } catch (err) {
    return handleRouteError(err);
  }
}

export async function DELETE() {
  try {
    const user = await requireUser();
    await deleteUserData(user.id);
    return jsonOk({ ok: true as const });
  } catch (err) {
    return handleRouteError(err);
  }
}

import { z } from 'zod';
import type { ListPantryResponse } from '@/contracts/api';
import { requireUser } from '@/lib/current-user';
import { handleRouteError, jsonError, jsonErrorFromZod, jsonOk } from '@/lib/http';
import { createPantryItem, listPantry } from '@/server/pantry/repo';
import { createPantryItemSchema } from '@/server/pantry/validation';

export const runtime = 'nodejs';

// SPEC F5 + §7. GET /api/pantry?sort=expiry|name&includeEmpty=false → { items }. POST → PantryItem.

const listQuery = z
  .object({
    sort: z.enum(['expiry', 'name']).default('expiry'),
    includeEmpty: z.enum(['true', 'false']).default('false').transform((v) => v === 'true'),
  })
  .strict();

export async function GET(req: Request) {
  try {
    const user = await requireUser();
    const parsed = listQuery.safeParse(Object.fromEntries(new URL(req.url).searchParams));
    if (!parsed.success) return jsonErrorFromZod(parsed.error);
    const items = await listPantry(user.id, user.tz, parsed.data);
    return jsonOk({ items } satisfies ListPantryResponse);
  } catch (err) {
    return handleRouteError(err);
  }
}

export async function POST(req: Request) {
  try {
    const user = await requireUser();
    const body = await req.json().catch(() => undefined);
    if (body === undefined) return jsonError('BAD_REQUEST', 'Body must be JSON');
    const parsed = createPantryItemSchema.safeParse(body);
    if (!parsed.success) return jsonErrorFromZod(parsed.error);
    return jsonOk(await createPantryItem(user.id, user.tz, parsed.data), { status: 201 });
  } catch (err) {
    return handleRouteError(err);
  }
}

import { requireUser } from '@/lib/current-user';
import { handleRouteError, isUuid, jsonError, jsonErrorFromZod, jsonOk } from '@/lib/http';
import { deletePantryItem, updatePantryItem } from '@/server/pantry/repo';
import { updatePantryItemSchema } from '@/server/pantry/validation';

export const runtime = 'nodejs';

// SPEC F5 + §7. PATCH → PantryItem (quantity changes write pantry_events). DELETE → { ok: true }.
// Another user's id (or a malformed one) → 404, never 403 (§13).

export async function PATCH(req: Request, ctx: { params: Promise<{ id: string }> }) {
  try {
    const user = await requireUser();
    const { id } = await ctx.params;
    if (!isUuid(id)) return jsonError('NOT_FOUND', 'Pantry item not found');
    const body = await req.json().catch(() => undefined);
    if (body === undefined) return jsonError('BAD_REQUEST', 'Body must be JSON');
    const parsed = updatePantryItemSchema.safeParse(body);
    if (!parsed.success) return jsonErrorFromZod(parsed.error);
    return jsonOk(await updatePantryItem(user.id, id, user.tz, parsed.data));
  } catch (err) {
    return handleRouteError(err);
  }
}

export async function DELETE(_req: Request, ctx: { params: Promise<{ id: string }> }) {
  try {
    const user = await requireUser();
    const { id } = await ctx.params;
    if (!isUuid(id)) return jsonError('NOT_FOUND', 'Pantry item not found');
    await deletePantryItem(user.id, id);
    return jsonOk({ ok: true as const });
  } catch (err) {
    return handleRouteError(err);
  }
}

import { requireUser } from '@/lib/current-user';
import { handleRouteError, isUuid, jsonError, jsonOk } from '@/lib/http';
import { restockPantryItem } from '@/server/pantry/repo';

export const runtime = 'nodejs';

// POST /api/pantry/:id/restock → PantryItem (team decision 2026-11-08, documented in contracts/api.ts).
// Refills an empty row to its initial quantity, clears the expiry, logs an 'add' event.
// 409 if the item is not empty; 422 if it has no recorded initial quantity.

export async function POST(_req: Request, ctx: { params: Promise<{ id: string }> }) {
  try {
    const user = await requireUser();
    const { id } = await ctx.params;
    if (!isUuid(id)) return jsonError('NOT_FOUND', 'Pantry item not found');
    return jsonOk(await restockPantryItem(user.id, id, user.tz));
  } catch (err) {
    return handleRouteError(err);
  }
}

