// SPEC F5 / §12 rules 5 & 9: expiry colour band plus text ("colour is never the only cue"), and
// "Best before" wording (team decision: always "Best before"). Grace days (UserProfile
// pastBestBeforeGraceDays, team decision 2026-11-08): an item up to N days past its date still
// counts as usable, so it gets the amber band instead of red. Pure; used on client and server.

export type ExpiryBand = 'expired' | 'grace' | 'soon' | 'week' | 'later' | 'none';

export interface ExpiryInfo {
  band: ExpiryBand;
  /** e.g. "Best before Nov 15 · 2 days", "Best before today", "Past best before · 3 days ago" */
  text: string;
  /** true when the item still counts as usable (not expired beyond grace). */
  usable: boolean;
}

const plural = (n: number, w: string) => `${n} ${w}${n === 1 ? '' : 's'}`;

/** 'Nov 15' (or 'Nov 15, 2027' when not in `currentYear`). Formats the calendar date, no time zone shift. */
export function formatBestBeforeDate(isoDate: string, currentYear: number): string {
  const [y, m, d] = isoDate.split('-').map(Number);
  const date = new Date(Date.UTC(y, m - 1, d));
  return new Intl.DateTimeFormat('en-US', {
    month: 'short',
    day: 'numeric',
    ...(y !== currentYear ? { year: 'numeric' } : {}),
    timeZone: 'UTC',
  }).format(date);
}

export function expiryInfo(
  expiryDate: string | null,
  daysToExpiry: number | null,
  graceDays = 0,
  currentYear: number = new Date().getFullYear(),
): ExpiryInfo {
  if (expiryDate == null || daysToExpiry == null) return { band: 'none', text: 'No date', usable: true };
  const grace = Math.max(0, Math.floor(graceDays));
  if (daysToExpiry < 0) {
    const ago = -daysToExpiry;
    const text = `Past best before · ${plural(ago, 'day')} ago`;
    return ago <= grace ? { band: 'grace', text, usable: true } : { band: 'expired', text, usable: false };
  }
  if (daysToExpiry === 0) return { band: 'soon', text: 'Best before today', usable: true };
  const when = `Best before ${formatBestBeforeDate(expiryDate, currentYear)} · ${plural(daysToExpiry, 'day')}`;
  if (daysToExpiry <= 3) return { band: 'soon', text: when, usable: true };
  if (daysToExpiry <= 7) return { band: 'week', text: when, usable: true };
  return { band: 'later', text: when, usable: true };
}

/** "Expiring soon" on /today: due within 3 days, or past the date but within the grace period. */
export function isExpiringSoon(daysToExpiry: number | null, graceDays = 0): boolean {
  if (daysToExpiry == null) return false;
  return daysToExpiry <= 3 && daysToExpiry >= -Math.max(0, Math.floor(graceDays));
}

/** Tailwind classes per band. Red / amber / yellow / neutral (F5). Yellow uses Tailwind's palette
 *  because the shared design tokens have no yellow; text always accompanies the colour. */
export const BAND_CLASSES: Record<ExpiryBand, { stripe: string; badge: string }> = {
  expired: { stripe: 'bg-danger', badge: 'bg-danger-soft text-danger' },
  grace: { stripe: 'bg-warn', badge: 'bg-warn-soft text-warn' },
  soon: { stripe: 'bg-warn', badge: 'bg-warn-soft text-warn' },
  week: { stripe: 'bg-yellow-400', badge: 'bg-yellow-100 text-yellow-900' },
  later: { stripe: 'bg-line', badge: 'bg-surface-2 text-muted' },
  none: { stripe: 'bg-line', badge: 'bg-surface-2 text-muted' },
};

import { describe, expect, it } from 'vitest';
import { expiryInfo, formatBestBeforeDate, isExpiringSoon } from './expiry';

describe('expiryInfo (F5 AC1, AC3)', () => {
  const Y = 2026;
  it('no date', () => {
    expect(expiryInfo(null, null, 0, Y)).toEqual({ band: 'none', text: 'No date', usable: true });
  });
  it('today shows 0 days as "Best before today"', () => {
    expect(expiryInfo('2026-11-08', 0, 0, Y)).toEqual({ band: 'soon', text: 'Best before today', usable: true });
  });
  it('≤3 days amber, ≤7 yellow, later neutral, with date text', () => {
    expect(expiryInfo('2026-11-10', 2, 0, Y)).toEqual({ band: 'soon', text: 'Best before Nov 10 · 2 days', usable: true });
    expect(expiryInfo('2026-11-09', 1, 0, Y).text).toBe('Best before Nov 9 · 1 day');
    expect(expiryInfo('2026-11-15', 7, 0, Y).band).toBe('week');
    expect(expiryInfo('2026-11-18', 10, 0, Y)).toEqual({ band: 'later', text: 'Best before Nov 18 · 10 days', usable: true });
  });
  it('past dates are red unless within the grace period', () => {
    expect(expiryInfo('2026-11-07', -1, 0, Y)).toEqual({ band: 'expired', text: 'Past best before · 1 day ago', usable: false });
    expect(expiryInfo('2026-11-06', -2, 3, Y)).toEqual({ band: 'grace', text: 'Past best before · 2 days ago', usable: true });
    expect(expiryInfo('2026-11-05', -3, 3, Y).band).toBe('grace');
    expect(expiryInfo('2026-11-04', -4, 3, Y).band).toBe('expired');
  });
  it('shows the year when it is not the current year', () => {
    expect(formatBestBeforeDate('2027-01-02', 2026)).toBe('Jan 2, 2027');
    expect(formatBestBeforeDate('2026-12-31', 2026)).toBe('Dec 31');
  });
});

describe('isExpiringSoon', () => {
  it('0..3 days by default; past dates only within grace', () => {
    expect([3, 0, 4, -1, null].map((d) => isExpiringSoon(d))).toEqual([true, true, false, false, false]);
    expect([-1, -2, -3].map((d) => isExpiringSoon(d, 2))).toEqual([true, true, false]);
  });
});

import type { ApiError, CreatePantryItemRequest, ListPantryResponse, UpdateMeRequest, UpdatePantryItemRequest } from '@/contracts/api';
import type { PantryItem, UserProfile } from '@/contracts/domain';

// Browser-side client for Workstream B routes. Throws ApiClientError with the server's message.

export class ApiClientError extends Error {
  constructor(
    message: string,
    public status: number,
    public code: string | null,
    public details?: unknown,
  ) {
    super(message);
  }
}

export async function api<T>(path: string, init?: RequestInit & { json?: unknown }): Promise<T> {
  const { json, ...rest } = init ?? {};
  const res = await fetch(path, {
    ...rest,
    headers: { ...(json !== undefined ? { 'Content-Type': 'application/json' } : {}), ...rest.headers },
    body: json !== undefined ? JSON.stringify(json) : rest.body,
  });
  const text = await res.text();
  const data = text ? (JSON.parse(text) as unknown) : null;
  if (!res.ok) {
    const err = (data as ApiError | null)?.error;
    throw new ApiClientError(err?.message ?? `Request failed (${res.status})`, res.status, err?.code ?? null, err?.details);
  }
  return data as T;
}

export const pantryApi = {
  list: (opts: { sort?: 'expiry' | 'name'; includeEmpty?: boolean } = {}) =>
    api<ListPantryResponse>(
      `/api/pantry?sort=${opts.sort ?? 'expiry'}&includeEmpty=${opts.includeEmpty ? 'true' : 'false'}`,
    ),
  create: (body: CreatePantryItemRequest) => api<PantryItem>('/api/pantry', { method: 'POST', json: body }),
  update: (id: string, body: UpdatePantryItemRequest) =>
    api<PantryItem>(`/api/pantry/${encodeURIComponent(id)}`, { method: 'PATCH', json: body }),
  remove: (id: string) => api<{ ok: true }>(`/api/pantry/${encodeURIComponent(id)}`, { method: 'DELETE' }),
  restock: (id: string) => api<PantryItem>(`/api/pantry/${encodeURIComponent(id)}/restock`, { method: 'POST', json: {} }),
};

export const meApi = {
  get: () => api<UserProfile>('/api/me'),
  update: (body: UpdateMeRequest) => api<UserProfile>('/api/me', { method: 'PATCH', json: body }),
  deleteAll: () => api<{ ok: true }>('/api/me', { method: 'DELETE' }),
};

