import type { Allergen, DietFlag, DisplayUnit } from '@/contracts/domain';

// UI labels. Records keyed by the contract unions, so adding an enum value fails to compile here.

export const ALLERGEN_LABELS: Record<Allergen, string> = {
  peanut: 'Peanuts',
  tree_nut: 'Tree nuts',
  sesame: 'Sesame',
  milk: 'Milk',
  egg: 'Eggs',
  fish: 'Fish',
  shellfish: 'Shellfish (crustaceans & molluscs)',
  soy: 'Soy',
  wheat_gluten: 'Wheat & gluten (incl. barley, oats, rye, triticale)',
  mustard: 'Mustard',
  sulphite: 'Sulphites',
};
export const ALLERGENS = Object.keys(ALLERGEN_LABELS) as Allergen[];

export const DIET_LABELS: Record<DietFlag, string> = {
  vegetarian: 'Vegetarian',
  vegan: 'Vegan',
  gluten_free: 'Gluten-free',
  dairy_free: 'Dairy-free',
  high_protein: 'High protein',
};
export const DIETS = Object.keys(DIET_LABELS) as DietFlag[];

export const UNIT_LABELS: Record<DisplayUnit, string> = {
  g: 'g',
  kg: 'kg',
  oz: 'oz',
  lb: 'lb',
  ml: 'ml',
  l: 'L',
  tsp: 'tsp',
  tbsp: 'tbsp',
  cup: 'cup',
  fl_oz: 'fl oz',
  pcs: 'pieces',
};

'use client';

import { useId, useState, type ReactNode } from 'react';
import type { Allergen, DisplayUnit, Nutrients } from '@/contracts/domain';
import { Button } from '@/components/ui';
import { unitDim } from '@/lib/units';
import { ALLERGENS, ALLERGEN_LABELS, UNIT_LABELS } from './labels';

// SPEC F3/F5: ONE form for manual entry, editing and Gemini label drafts. Requires name, quantity
// and unit; nutrition optional. Nothing is saved until the user presses the submit button
// (confirm-before-save, §12 rule 2). Flagged fields are highlighted.

export type NutritionBasis = '100g' | '100ml' | 'unit';
export type FlaggableField = keyof Nutrients | 'servingSize' | 'packageQuantity' | 'name';

export interface ProductFormValues {
  name: string;
  brand: string | null;
  quantity: number;
  displayUnit: DisplayUnit;
  gramsPerUnit: number | null;
  densityGPerMl: number | null;
  expiryDate: string | null;
  expirySource: 'photo' | 'manual' | null;
  expiryRawText: string | null;
  nutritionBasis: NutritionBasis;
  nutrition: Nutrients | null;
  servingSizeBase: number | null;
  allergenTags: Allergen[];
}

export interface ProductFormInitial extends Partial<Omit<ProductFormValues, 'quantity'>> {
  quantity?: number | null;
}

const UNITS = Object.keys(UNIT_LABELS) as DisplayUnit[];
const NUTRIENT_FIELDS: Array<{ key: 'energyKcal' | 'proteinG' | 'carbohydrateG' | 'fatG'; label: string; unit: string }> = [
  { key: 'energyKcal', label: 'Calories', unit: 'kcal' },
  { key: 'proteinG', label: 'Protein', unit: 'g' },
  { key: 'carbohydrateG', label: 'Carbohydrate (total)', unit: 'g' },
  { key: 'fatG', label: 'Fat', unit: 'g' },
];

const str = (n: number | null | undefined) => (n == null ? '' : String(n));
/** '' → null; otherwise a finite number ≥ 0, or NaN for invalid input. */
function parseNum(s: string): number | null {
  const t = s.trim().replace(',', '.');
  if (t === '') return null;
  const n = Number(t);
  return Number.isFinite(n) && n >= 0 ? n : Number.NaN;
}

const inputClass = (flagged = false) =>
  `min-h-11 w-full rounded-xl border bg-surface px-3 text-ink ${flagged ? 'border-warn ring-2 ring-warn/40' : 'border-line'}`;

export function ProductForm({
  initial,
  flaggedFields = [],
  badge,
  expirySlot,
  submitLabel = 'Save',
  onSubmit,
  onCancel,
}: {
  initial?: ProductFormInitial;
  flaggedFields?: FlaggableField[];
  /** e.g. <Badge tone="ai">Read by AI, please confirm</Badge> */
  badge?: ReactNode;
  /** Extra controls under the date field, e.g. "Photo of date" (F4). */
  expirySlot?: ReactNode;
  submitLabel?: string;
  onSubmit: (values: ProductFormValues) => Promise<void>;
  onCancel?: () => void;
}) {
  const id = useId();
  const flagged = new Set<FlaggableField>(flaggedFields);

  const [name, setName] = useState(initial?.name ?? '');
  const [brand, setBrand] = useState(initial?.brand ?? '');
  const [quantity, setQuantity] = useState(str(initial?.quantity));
  const [unit, setUnit] = useState<DisplayUnit>(initial?.displayUnit ?? 'g');
  const [gramsPerUnit, setGramsPerUnit] = useState(str(initial?.gramsPerUnit));
  const [density, setDensity] = useState(str(initial?.densityGPerMl));
  const [hasExpiry, setHasExpiry] = useState(initial?.expiryDate != null);
  const [expiryDate, setExpiryDate] = useState(initial?.expiryDate ?? '');
  const [basis, setBasis] = useState<NutritionBasis>(initial?.nutritionBasis ?? defaultBasis(initial?.displayUnit ?? 'g'));
  const [nutrients, setNutrients] = useState<Record<string, string>>(() =>
    Object.fromEntries(NUTRIENT_FIELDS.map((f) => [f.key, str(initial?.nutrition?.[f.key])])),
  );
  const [servingSize, setServingSize] = useState(str(initial?.servingSizeBase));
  const [allergens, setAllergens] = useState<Allergen[]>(initial?.allergenTags ?? []);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  // Photo-read dates keep their source/raw text only while the user leaves the date unchanged.
  const initialExpiry = initial?.expiryDate ?? null;
  const dim = unitDim(unit);

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    const q = parseNum(quantity);
    if (!name.trim()) return setError('Enter a name.');
    if (q === null || Number.isNaN(q) || q <= 0) return setError('Enter a quantity greater than 0.');
    if (hasExpiry && !/^\d{4}-\d{2}-\d{2}$/.test(expiryDate)) return setError('Pick a best-before date, or choose "No date".');

    const nums = Object.fromEntries(NUTRIENT_FIELDS.map((f) => [f.key, parseNum(nutrients[f.key] ?? '')])) as Record<
      (typeof NUTRIENT_FIELDS)[number]['key'],
      number | null
    >;
    if (Object.values(nums).some((v) => Number.isNaN(v))) return setError('Nutrition values must be numbers ≥ 0.');
    const serving = parseNum(servingSize);
    const gpu = parseNum(gramsPerUnit);
    const dens = parseNum(density);
    if ([serving, gpu, dens].some((v) => Number.isNaN(v) || v === 0)) return setError('Sizes must be numbers greater than 0.');

    const anyNutrient = Object.values(nums).some((v) => v !== null);
    const dateUnchanged = hasExpiry && expiryDate === initialExpiry;
    setSaving(true);
    try {
      await onSubmit({
        name: name.trim(),
        brand: brand.trim() || null,
        quantity: q,
        displayUnit: unit,
        gramsPerUnit: dim === 'count' ? gpu : (initial?.gramsPerUnit ?? null),
        densityGPerMl: dim === 'volume' ? dens : (initial?.densityGPerMl ?? null),
        expiryDate: hasExpiry ? expiryDate : null,
        expirySource: hasExpiry ? (dateUnchanged ? (initial?.expirySource ?? 'manual') : 'manual') : null,
        expiryRawText: hasExpiry && dateUnchanged ? (initial?.expiryRawText ?? null) : null,
        nutritionBasis: basis,
        nutrition: anyNutrient
          ? { energyKcal: nums.energyKcal, proteinG: nums.proteinG, carbohydrateG: nums.carbohydrateG, fatG: nums.fatG }
          : null,
        servingSizeBase: basis === 'unit' ? null : serving,
        allergenTags: allergens,
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Could not save.');
    } finally {
      setSaving(false);
    }
  }

  const toggleAllergen = (a: Allergen) => setAllergens((xs) => (xs.includes(a) ? xs.filter((x) => x !== a) : [...xs, a]));

  return (
    <form onSubmit={submit} className="grid gap-5" noValidate>
      {badge}

      <div className="grid gap-4 sm:grid-cols-2">
        <label className="grid gap-1 text-sm font-semibold">
          Name <span className="sr-only">(required)</span>
          <input
            className={inputClass(flagged.has('name'))}
            value={name}
            onChange={(e) => setName(e.target.value)}
            maxLength={120}
            required
            autoComplete="off"
          />
        </label>
        <label className="grid gap-1 text-sm font-semibold">
          Brand <span className="font-normal text-muted">(optional)</span>
          <input className={inputClass()} value={brand} onChange={(e) => setBrand(e.target.value)} maxLength={120} autoComplete="off" />
        </label>
      </div>

      <fieldset className="grid gap-2">
        <legend className="mb-1 text-sm font-semibold">Quantity you have</legend>
        <div className="flex gap-2">
          <input
            aria-label="Quantity"
            className={`${inputClass(flagged.has('packageQuantity'))} max-w-40`}
            inputMode="decimal"
            value={quantity}
            onChange={(e) => setQuantity(e.target.value)}
            required
          />
          <select
            aria-label="Unit"
            className={`${inputClass()} max-w-36`}
            value={unit}
            onChange={(e) => {
              const u = e.target.value as DisplayUnit;
              setUnit(u);
              if (unitDim(u) !== dim) setBasis(defaultBasis(u));
            }}
          >
            {UNITS.map((u) => (
              <option key={u} value={u}>
                {UNIT_LABELS[u]}
              </option>
            ))}
          </select>
        </div>
        {dim === 'count' && (
          <label className="grid max-w-xs gap-1 text-sm">
            Weight of one piece (g) <span className="text-muted">optional, helps convert recipes</span>
            <input className={inputClass()} inputMode="decimal" value={gramsPerUnit} onChange={(e) => setGramsPerUnit(e.target.value)} />
          </label>
        )}
        {dim === 'volume' && (
          <label className="grid max-w-xs gap-1 text-sm">
            Density (g per ml) <span className="text-muted">optional, e.g. 1.03 for milk</span>
            <input className={inputClass()} inputMode="decimal" value={density} onChange={(e) => setDensity(e.target.value)} />
          </label>
        )}
      </fieldset>

      <fieldset className="grid gap-2">
        <legend className="mb-1 text-sm font-semibold">Best before</legend>
        <div className="flex flex-wrap items-center gap-4 text-sm">
          <label className="flex min-h-11 items-center gap-2">
            <input type="radio" name={`${id}-expiry`} checked={hasExpiry} onChange={() => setHasExpiry(true)} /> Enter date
          </label>
          <label className="flex min-h-11 items-center gap-2">
            <input type="radio" name={`${id}-expiry`} checked={!hasExpiry} onChange={() => setHasExpiry(false)} /> No date
          </label>
        </div>
        {hasExpiry && (
          <input
            type="date"
            aria-label="Best-before date"
            className={`${inputClass()} max-w-52`}
            value={expiryDate}
            onChange={(e) => setExpiryDate(e.target.value)}
          />
        )}
        {hasExpiry && expiryDate === initialExpiry && initial?.expiryRawText && (
          <p className="text-sm text-muted">
            Read: <code className="rounded bg-surface-2 px-1">{initial.expiryRawText}</code>
          </p>
        )}
        {expirySlot}
      </fieldset>

      <fieldset className="grid gap-3">
        <legend className="mb-1 text-sm font-semibold">
          Nutrition <span className="font-normal text-muted">(optional, but helps track calories)</span>
        </legend>
        <label className="grid max-w-xs gap-1 text-sm">
          Values are
          <select className={inputClass()} value={basis} onChange={(e) => setBasis(e.target.value as NutritionBasis)}>
            <option value="100g">per 100 g</option>
            <option value="100ml">per 100 ml</option>
            <option value="unit">per piece</option>
          </select>
        </label>
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
          {NUTRIENT_FIELDS.map((f) => (
            <label key={f.key} className="grid gap-1 text-sm">
              {f.label} ({f.unit})
              <input
                className={inputClass(flagged.has(f.key))}
                inputMode="decimal"
                value={nutrients[f.key]}
                onChange={(e) => setNutrients((n) => ({ ...n, [f.key]: e.target.value }))}
              />
            </label>
          ))}
        </div>
        {basis !== 'unit' && (
          <label className="grid max-w-xs gap-1 text-sm">
            Serving size ({basis === '100ml' ? 'ml' : 'g'}) <span className="text-muted">optional</span>
            <input
              className={inputClass(flagged.has('servingSize'))}
              inputMode="decimal"
              value={servingSize}
              onChange={(e) => setServingSize(e.target.value)}
            />
          </label>
        )}
      </fieldset>

      <fieldset>
        <legend className="mb-2 text-sm font-semibold">Contains allergens</legend>
        <div className="flex flex-wrap gap-2">
          {ALLERGENS.map((a) => (
            <label
              key={a}
              className={`flex min-h-11 cursor-pointer items-center gap-2 rounded-full border px-3 text-sm ${
                allergens.includes(a) ? 'border-accent bg-accent-soft text-accent' : 'border-line'
              }`}
            >
              <input type="checkbox" className="sr-only" checked={allergens.includes(a)} onChange={() => toggleAllergen(a)} />
              <span aria-hidden>{allergens.includes(a) ? '✓' : '+'}</span> {ALLERGEN_LABELS[a]}
            </label>
          ))}
        </div>
        <p className="mt-2 text-xs text-muted">Always check product labels for allergens.</p>
      </fieldset>

      {error && (
        <p role="alert" className="rounded-xl bg-danger-soft px-3 py-2 text-sm text-danger">
          {error}
        </p>
      )}
      <div className="flex flex-wrap gap-3">
        <Button type="submit" disabled={saving}>
          {saving ? 'Saving…' : submitLabel}
        </Button>
        {onCancel && (
          <Button variant="secondary" onClick={onCancel} disabled={saving}>
            Cancel
          </Button>
        )}
      </div>
    </form>
  );
}

function defaultBasis(unit: DisplayUnit): NutritionBasis {
  const d = unitDim(unit);
  return d === 'volume' ? '100ml' : d === 'count' ? 'unit' : '100g';
}

import type { Nutrients, PantryItem } from '@/contracts/domain';

// F10 (item part): "Per 100 g: 59 kcal · 10 g protein · 3.6 g carbs · 0.4 g fat". Pure.

const fmt = (n: number) => String(Math.round(n * 10) / 10);

export function nutrientsText(n: Nutrients | null | undefined): string | null {
  if (!n) return null;
  const parts: string[] = [];
  if (n.energyKcal != null) parts.push(`${Math.round(n.energyKcal)} kcal`);
  if (n.proteinG != null) parts.push(`${fmt(n.proteinG)} g protein`);
  if (n.carbohydrateG != null) parts.push(`${fmt(n.carbohydrateG)} g carbs`);
  if (n.fatG != null) parts.push(`${fmt(n.fatG)} g fat`);
  return parts.length ? parts.join(' · ') : null;
}

export function basisLabel(basis: PantryItem['nutritionBasis']): string {
  return basis === '100g' ? 'Per 100 g' : basis === '100ml' ? 'Per 100 ml' : 'Per piece';
}

/** Lines to show under a pantry item; empty when no nutrition is known. */
export function itemNutritionLines(item: Pick<PantryItem, 'nutritionBasis' | 'nutrition' | 'perServing' | 'servingSizeBase'>): string[] {
  const lines: string[] = [];
  const per = nutrientsText(item.nutrition);
  if (per) lines.push(`${basisLabel(item.nutritionBasis)}: ${per}`);
  const serving = nutrientsText(item.perServing);
  if (serving && item.servingSizeBase) {
    const u = item.nutritionBasis === '100ml' ? 'ml' : 'g';
    lines.push(`Per serving (${fmt(item.servingSizeBase)} ${u}): ${serving}`);
  }
  return lines;
}

'use client';

import { useCallback, useState } from 'react';
import type { CreatePantryItemRequest } from '@/contracts/api';
import type { PantryItem } from '@/contracts/domain';
import { Badge, Button, Card, Dialog, useToast } from '@/components/ui';
import { fromBase } from '@/lib/units';
import { pantryApi } from './api';
import { BAND_CLASSES, expiryInfo } from './expiry';
import { ALLERGEN_LABELS, UNIT_LABELS } from './labels';
import { itemNutritionLines } from './nutrition-text';
import { ProductForm, type ProductFormValues } from './ProductForm';

// SPEC F5 + F10 (item part): pantry list sorted by soonest best-before, colour band + text,
// inline adjust / discard / edit / delete, "Include empty" with Restock.

type Sort = 'expiry' | 'name';

export function PantryList({ initialItems, graceDays, addSlot }: { initialItems: PantryItem[]; graceDays: number; addSlot?: React.ReactNode }) {
  const toast = useToast();
  const [items, setItems] = useState(initialItems);
  const [sort, setSort] = useState<Sort>('expiry');
  const [includeEmpty, setIncludeEmpty] = useState(false);
  const [adding, setAdding] = useState(false);
  const [editing, setEditing] = useState<PantryItem | null>(null);
  const [deleting, setDeleting] = useState<PantryItem | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const reload = useCallback(async (next: { sort: Sort; includeEmpty: boolean }) => {
    setLoading(true);
    setError(null);
    try {
      setItems((await pantryApi.list(next)).items);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Could not load your pantry.');
    } finally {
      setLoading(false);
    }
  }, []);

  const view = { sort, includeEmpty };
  const run = async (action: () => Promise<unknown>, done: string) => {
    setError(null);
    try {
      await action();
      toast(done);
      await reload(view);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Something went wrong.');
    }
  };

  async function addManual(v: ProductFormValues) {
    const body: CreatePantryItemRequest = { ...v, gtin: null, source: 'manual', userVerified: true };
    await pantryApi.create(body);
    setAdding(false);
    toast(`Added ${v.name}`);
    await reload(view);
  }

  async function saveEdit(item: PantryItem, v: ProductFormValues) {
    await pantryApi.update(item.id, {
      name: v.name,
      brand: v.brand,
      quantity: v.quantity,
      displayUnit: v.displayUnit,
      gramsPerUnit: v.gramsPerUnit,
      densityGPerMl: v.densityGPerMl,
      expiryDate: v.expiryDate,
      expirySource: v.expirySource,
      expiryRawText: v.expiryRawText,
      nutritionBasis: v.nutritionBasis,
      nutrition: v.nutrition,
      servingSizeBase: v.servingSizeBase,
      allergenTags: v.allergenTags,
      userVerified: true,
    });
    setEditing(null);
    toast(`Saved ${v.name}`);
    await reload(view);
  }

  return (
    <div className="grid gap-4">
      <div className="flex flex-wrap items-center gap-3">
        {addSlot}
        <Button variant={addSlot ? 'secondary' : 'primary'} onClick={() => setAdding(true)}>
          Add manually
        </Button>
        <label className="ml-auto flex min-h-11 items-center gap-2 text-sm">
          Sort
          <select
            className="min-h-11 rounded-xl border border-line bg-surface px-3"
            value={sort}
            onChange={(e) => {
              const s = e.target.value as Sort;
              setSort(s);
              void reload({ sort: s, includeEmpty });
            }}
          >
            <option value="expiry">Best before (soonest first)</option>
            <option value="name">Name</option>
          </select>
        </label>
        <label className="flex min-h-11 items-center gap-2 text-sm">
          <input
            type="checkbox"
            checked={includeEmpty}
            onChange={(e) => {
              setIncludeEmpty(e.target.checked);
              void reload({ sort, includeEmpty: e.target.checked });
            }}
          />
          Include empty
        </label>
      </div>

      {error && (
        <p role="alert" className="rounded-xl bg-danger-soft px-3 py-2 text-sm text-danger">
          {error}
        </p>
      )}
      {loading && <p className="text-sm text-muted" aria-live="polite">Loading your pantry…</p>}

      {items.length === 0 && !loading ? (
        <Card>
          <p className="font-semibold">Your pantry is empty.</p>
          <p className="mt-1 text-sm text-muted">Scan a barcode or add an item by hand to get started.</p>
        </Card>
      ) : (
        <ul className="grid gap-3">
          {items.map((item) => (
            <PantryRow
              key={item.id}
              item={item}
              graceDays={graceDays}
              onAdjust={(quantity) => run(() => pantryApi.update(item.id, { quantity, adjustReason: 'manual_adjust' }), `Updated ${item.name}`)}
              onDiscard={() => run(() => pantryApi.update(item.id, { adjustReason: 'discard' }), `Discarded ${item.name}`)}
              onRestock={() => run(() => pantryApi.restock(item.id), `Restocked ${item.name}`)}
              onEdit={() => setEditing(item)}
              onDelete={() => setDeleting(item)}
            />
          ))}
        </ul>
      )}

      <Dialog open={adding} onClose={() => setAdding(false)} title="Add an item">
        {adding && <ProductForm submitLabel="Add to pantry" onSubmit={addManual} onCancel={() => setAdding(false)} />}
      </Dialog>

      <Dialog open={editing !== null} onClose={() => setEditing(null)} title={editing ? `Edit ${editing.name}` : 'Edit'}>
        {editing && (
          <ProductForm
            key={editing.id}
            initial={{
              ...editing,
              quantity: fromBase(editing.quantityBase, editing.dim, editing.displayUnit),
              expiryRawText: null,
            }}
            submitLabel="Save changes"
            onSubmit={(v) => saveEdit(editing, v)}
            onCancel={() => setEditing(null)}
          />
        )}
      </Dialog>

      <Dialog open={deleting !== null} onClose={() => setDeleting(null)} title="Delete item?">
        {deleting && (
          <div className="grid gap-4">
            <p>
              Delete <strong>{deleting.name}</strong> from your pantry? Meals you already logged keep their nutrition.
            </p>
            <div className="flex gap-3">
              <Button
                variant="danger"
                onClick={() => {
                  const d = deleting;
                  setDeleting(null);
                  void run(() => pantryApi.remove(d.id), `Deleted ${d.name}`);
                }}
              >
                Delete
              </Button>
              <Button variant="secondary" onClick={() => setDeleting(null)}>
                Cancel
              </Button>
            </div>
          </div>
        )}
      </Dialog>
    </div>
  );
}

function PantryRow({
  item,
  graceDays,
  onAdjust,
  onDiscard,
  onRestock,
  onEdit,
  onDelete,
}: {
  item: PantryItem;
  graceDays: number;
  onAdjust: (quantity: number) => Promise<void>;
  onDiscard: () => Promise<void>;
  onRestock: () => Promise<void>;
  onEdit: () => void;
  onDelete: () => void;
}) {
  const info = expiryInfo(item.expiryDate, item.daysToExpiry, graceDays);
  const band = BAND_CLASSES[info.band];
  const empty = item.quantityBase <= 0;
  const current = fromBase(item.quantityBase, item.dim, item.displayUnit) ?? 0;
  const [adjusting, setAdjusting] = useState(false);
  const [value, setValue] = useState(String(Math.round(current * 100) / 100));
  const nutrition = itemNutritionLines(item);

  return (
    <li className="relative overflow-hidden rounded-2xl border border-line bg-surface">
      <span aria-hidden className={`absolute inset-y-0 left-0 w-1.5 ${band.stripe}`} />
      <div className="grid gap-2 py-4 pl-5 pr-4">
        <div className="flex flex-wrap items-start gap-x-3 gap-y-1">
          <div className="min-w-0 flex-1">
            <p className="font-semibold">
              {item.name}
              {item.brand && <span className="font-normal text-muted"> · {item.brand}</span>}
            </p>
            <p className="text-sm">
              {empty ? <span className="font-semibold text-muted">Empty</span> : item.quantityDisplay}
            </p>
          </div>
          <span className={`rounded-full px-2.5 py-0.5 text-xs font-semibold ${band.badge}`}>{info.text}</span>
        </div>

        {nutrition.map((line) => (
          <p key={line} className="text-xs text-muted">
            {line}
          </p>
        ))}
        {item.allergenTags.length > 0 && (
          <div className="flex flex-wrap gap-1">
            {item.allergenTags.map((a) => (
              <Badge key={a}>Contains {ALLERGEN_LABELS[a].split(' (')[0].toLowerCase()}</Badge>
            ))}
          </div>
        )}
        {(item.source === 'openfoodfacts' || item.source === 'dataandapis') && (
          <p className="text-xs text-muted">Product data: Open Food Facts (ODbL)</p>
        )}

        {adjusting ? (
          <form
            className="flex flex-wrap items-center gap-2"
            onSubmit={async (e) => {
              e.preventDefault();
              const q = Number(value.replace(',', '.'));
              if (!Number.isFinite(q) || q < 0) return;
              await onAdjust(q);
              setAdjusting(false);
            }}
          >
            <label className="flex items-center gap-2 text-sm">
              Now have
              <input
                className="min-h-11 w-28 rounded-xl border border-line bg-surface px-3"
                inputMode="decimal"
                value={value}
                onChange={(e) => setValue(e.target.value)}
                autoFocus
              />
              {UNIT_LABELS[item.displayUnit]}
            </label>
            <Button type="submit">Save</Button>
            <Button variant="ghost" onClick={() => setAdjusting(false)}>
              Cancel
            </Button>
          </form>
        ) : (
          <div className="flex flex-wrap gap-2">
            {empty ? (
              <Button variant="secondary" onClick={() => void onRestock()}>
                Restock
              </Button>
            ) : (
              <>
                <Button variant="secondary" onClick={() => setAdjusting(true)}>
                  Adjust
                </Button>
                <Button variant="secondary" onClick={() => void onDiscard()}>
                  Discard
                </Button>
              </>
            )}
            <Button variant="ghost" onClick={onEdit}>
              Edit
            </Button>
            <Button variant="ghost" onClick={onDelete}>
              Delete
            </Button>
          </div>
        )}
      </div>
    </li>
  );
}

